impl<T: gx::Real> Scalar<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        t0
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (4 mul, 0 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Scalar<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[0] * t0;
        let t2 = x[0] * t1;
        let t3 = t2.recip();
        let t4 = t1 * t3;
        Scalar::from_coeffs([t4])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[0] * x[0];
        let s0 = (p0).abs().sqrt().recip();
        let t0 = x[0] * s0;
        gx::Unit::new_unchecked(Scalar::from_coeffs([t0]))
    }

    /// The principal square root of a unit versor, `normalize(1 + R)` (not defined for `R = -1`).
    #[inline(always)]
    pub fn sqrt(self) -> gx::Unit<Self> {
        let mut c = self.c;
        c[0] = c[0] + T::one();
        Scalar::from_coeffs(c).normalized()
    }

}

impl<T: gx::Coef> gx::NewtonStep for Scalar<(), T> {
    /// `(3 â x ~x) x / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[0] * t0;
        let t3 = x[0] * T::from_ratio(3, 2);
        let t4 = (-t1).mul_add(T::from_ratio(1, 2), t3);
        Scalar::from_coeffs([t4])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

impl<T: gx::Real> gx::Inverse for Scalar<(), T> {
    type Output = Scalar<(), T>;
    #[inline(always)]
    fn inverse(self) -> Self::Output {
        Self::inverse(self)
    }
}

