    #[inline(always)]
    pub fn zero() -> Self {
        Bivector { c: [S::from_flat(&mut |_| T::zero(), 0); 10] }
    }

    /// Every coefficient mapped by `f`, kind and slots kept: to `Complex`, `gx::Dual` or `f32`
    /// (see [`gx::Extensor::map_coefs`]).
