        let t12 = x[10] * t1;
        let t14 = x[6] * t4;
        let t16 = x[10] * t2;
        let t19 = x[5] * t2;
        let t20 = x[6] * t1;
        let t23 = x[5] * h0;
        let t24 = x[6] * t0;
        let t26 = x[4] * t1;
        let t28 = x[6] * h0;
        let t31 = x[8] * t2;
        let t32 = x[9] * t1;
        let t34 = x[7] * t2;
        let t36 = x[9] * t0;
        let t39 = x[8] * t0;
